func (c *ProxmoxCredentials) Zeroize() {
    if c == nil {
        return
    }
    for i := range c.Password {
        c.Password[i] = 0
    }
    c.Password = nil
    for i := range c.APIToken {
        c.APIToken[i] = 0
    }
    c.APIToken = nil
}

